<script setup>
import {ref,reactive,computed,onMounted} from 'vue'
import smCrypto from '../utils/smCrypto'
import RegistrationForm from './RegistrationForm.vue'
import LifecyclePanel from './LifecyclePanel.vue'
import SrmModal from '../srm-ui/SrmModal.vue'
import SrmDrawer from '../srm-ui/SrmDrawer.vue'
import SrmStatus from '../srm-ui/SrmStatus.vue'
const props=defineProps({initialToken:{type:String,default:''},initialView:{type:String,default:'suppliers'},embedded:{type:Boolean,default:false}})
const realm=ref(props.initialToken?'b':sessionStorage.getItem('srm-active-realm')||'b'),token=ref(props.initialToken||sessionStorage.getItem('srm-real-'+realm.value)||''),context=ref(null)
const previewUrl=ref(''),previewType=ref('')
const registrationOpen=ref(false)
const error=ref(''),notice=ref(''),busy=ref(false),view=ref(props.initialView),selected=ref(null),tab=ref('profile'),mode=ref(''),categories=ref([]),rows=ref([]),total=ref(0),alerts=ref([]),page=ref(1),search=ref(''),category=ref(''),status=ref(''),tier=ref(''),orgFilter=ref(''),sortBy=ref('createTime'),sortOrder=ref('DESC')
const loginForm=reactive({account:'',password:'',validCode:'',validCodeReqNo:''}),captcha=ref(''),captchaOpen=ref(false),form=reactive({}),file=ref(null)
const statusLabels={POTENTIAL:'潜在供应商',REVIEWING:'审核中',CORRECTION:'补正中',QUALIFIED:'合格供应商',FROZEN:'已冻结',ELIMINATED:'已淘汰'}
const tierLabels={STRATEGIC:'战略',PREFERRED:'优选',QUALIFIED:'合格',TEMPORARY:'临时',WATCH:'观察'}
const certLabels={BUSINESS_LICENSE:'营业执照',ISO9001:'ISO9001',IATF16949:'IATF16949',ENVIRONMENT:'环保资质',OTHER:'其他'}
const roleLabels={ADMIN:'管理员',QUOTE:'报价员',SHIP:'发货员',QUALITY:'质量对接',FINANCE:'财务'}
const operationLabels={SUPPLIER_CREATED:'新建档案',SUPPLIER_UPDATED:'更新档案',CERTIFICATE_SAVED:'保存资质版本',CONTACT_CREATED:'新增联系人',CONTACT_UPDATED:'修改联系人',PORTAL_ACCOUNT_BOUND:'开通门户账号',TIER_UPDATED:'调整等级',ATTACHMENT_UPLOADED:'上传私有附件'}
const base=computed(()=>realm.value==='c'?'/client/c/srm/v1':'/srm/v1')
let timer
function toast(text){notice.value=text;clearTimeout(timer);timer=setTimeout(()=>notice.value='',4500)}
async function request(path,body,method='GET',raw=false){
 const requestToken=token.value;const options={method,headers:{token:requestToken}}
 if(body instanceof FormData)options.body=body
 else if(body!==undefined){options.body=JSON.stringify(body);options.headers['Content-Type']='application/json'}
 const response=await fetch('/api'+path,options)
 if(raw && !response.headers.get('content-type')?.includes('json')){if(!response.ok)throw new Error('下载失败');return response.blob()}
 const result=await response.json();if(requestToken && requestToken!==token.value && !path.startsWith('/auth/'))throw new Error('登录会话已变化，请刷新后重试')
 if(result.code!==200){if(result.code===401){context.value=null;token.value='';sessionStorage.removeItem('srm-real-'+realm.value)}throw new Error(result.msg||'请求失败')}
 return result.data
}
const api=(path,body,method='GET',raw=false)=>request(base.value+path,body,method,raw)
async function captchaConfig(){
 try{const list=await request('/dev/config/sysBaseList');captchaOpen.value=list.some(x=>x.configKey==='SNOWY_SYS_DEFAULT_CAPTCHA_OPEN_FLAG_FOR_'+realm.value.toUpperCase()&&String(x.configValue)==='true');if(captchaOpen.value)await refreshCaptcha()}catch(e){error.value='无法连接登录服务，请检查后端启动状态'}
}
async function refreshCaptcha(){try{const c=await request('/auth/'+realm.value+'/getPicCaptcha');captcha.value=c.validCodeBase64;loginForm.validCodeReqNo=c.validCodeReqNo}catch(e){error.value=e.message}}
async function login(){busy.value=true;error.value='';try{
 token.value=await request('/auth/'+realm.value+'/doLogin',{account:loginForm.account,password:smCrypto.doSm2Encrypt(loginForm.password),device:'PC',validCode:loginForm.validCode,validCodeReqNo:loginForm.validCodeReqNo},'POST')
 loginForm.password='';sessionStorage.setItem('srm-real-'+realm.value,token.value);sessionStorage.setItem('srm-active-realm',realm.value);await initialize()
 }catch(e){error.value=e.message;if(captchaOpen.value)await refreshCaptcha()}finally{busy.value=false}}
function closePreview(){if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value=''}
async function preview(fid){try{const blob=await api('/attachments/'+fid,undefined,'GET',true);closePreview();previewType.value=blob.type;previewUrl.value=URL.createObjectURL(blob)}catch(e){toast(e.message)}}
function clearData(){closePreview();view.value=props.initialView;tab.value='profile';rows.value=[];total.value=0;selected.value=null;alerts.value=[];search.value='';category.value='';status.value='';tier.value='';orgFilter.value='';sortBy.value='createTime';sortOrder.value='DESC';page.value=1;mode.value='';for(const k of Object.keys(form))delete form[k]}
async function initialize(){clearData();context.value=await api('/session/context');categories.value=await api('/categories');await load();await loadAlerts()}
async function load(){busy.value=true;error.value='';try{const q=new URLSearchParams({current:page.value,size:20,searchKey:search.value,category:category.value,status:status.value,tier:tier.value,orgId:orgFilter.value,sortBy:sortBy.value,sortOrder:sortOrder.value});const p=await api('/suppliers?'+q);rows.value=p.records;total.value=p.total}catch(e){error.value=e.message;rows.value=[]}finally{busy.value=false}}
async function loadAlerts(){try{alerts.value=await api('/alerts')}catch(e){error.value=e.message}}
async function show(s){error.value='';try{selected.value=await api('/suppliers/'+s.id);tab.value='profile'}catch(e){toast(e.message)}}
function closeSupplier(){selected.value=null;tab.value='profile'}
async function refreshSelected(){const sid=selected.value?.id;if(!sid)return;const next=await api('/suppliers/'+sid);if(selected.value?.id===sid)selected.value=next;await load();await loadAlerts()}
function open(type,item){mode.value=type;error.value='';file.value=null;for(const k of Object.keys(form))delete form[k]
 if(type==='create')Object.assign(form,{supplierCode:'',name:'',category:categories.value.find(c=>c.enabled)?.code||'',creditCode:'',bankAccount:'',bankName:'',address:''})
 if(type==='edit')Object.assign(form,{name:selected.value.name,category:selected.value.category,bankName:selected.value.bankName||'',address:selected.value.address||'',creditCode:'',bankAccount:'',rowVersion:selected.value.rowVersion})
 if(type==='certificate')Object.assign(form,{certType:item?.certType||'BUSINESS_LICENSE',certNo:'',validFrom:new Date().toISOString().slice(0,10),validTo:'',previousId:item?.id||null})
 if(type==='contact')Object.assign(form,{name:'',phone:'',email:'',roles:['ADMIN'],enabled:true,rowVersion:0})
 if(type==='contactEdit')Object.assign(form,{id:item.id,name:item.name,phone:'',email:item.email||'',roles:[...item.roles],enabled:item.enabled,rowVersion:item.rowVersion})
 if(type==='access')Object.assign(form,{id:item.id,roles:[...item.roles],enabled:item.enabled,rowVersion:item.rowVersion})
 if(type==='account')Object.assign(form,{id:item.id,account:'',password:''})
 if(type==='category')Object.assign(form,{originalCode:item?.code||'',code:item?.code||'',name:item?.name||'',requiredCerts:item?JSON.parse(item.requiredCerts):['BUSINESS_LICENSE'],enabled:item?.enabled??true,rowVersion:item?.rowVersion||0})
 if(type==='tier')Object.assign(form,{tier:selected.value.tier,rowVersion:selected.value.rowVersion})
}
async function save(){busy.value=true;error.value='';try{
 if(mode.value==='create'){selected.value=await api('/suppliers',{...form},'POST');tab.value='profile';await load()}
 if(mode.value==='edit'){const p={...form};if(!p.creditCode)delete p.creditCode;if(!p.bankAccount)delete p.bankAccount;selected.value=await api('/suppliers/'+selected.value.id+'/edit',p,'POST');await load()}
 if(mode.value==='certificate'){if(!file.value)throw new Error('请先选择资质附件');const data=new FormData();data.append('file',file.value);const attachment=await api('/suppliers/'+selected.value.id+'/attachments',data,'POST');await api('/suppliers/'+selected.value.id+'/certificates',{...form,fileId:attachment.fileId},'POST');await refreshSelected()}
 if(['contact','contactEdit','access'].includes(mode.value)){const p={...form};delete p.id;const suffix=mode.value==='contact'?'':('/'+form.id+(mode.value==='access'?'/access':''));await api('/suppliers/'+selected.value.id+'/contacts'+suffix,p,'POST');await refreshSelected()}
 if(mode.value==='account'){await api('/suppliers/'+selected.value.id+'/contacts/'+form.id+'/account',{account:form.account,passwordCipher:smCrypto.doSm2Encrypt(form.password)},'POST');form.password='';await refreshSelected()}
 if(mode.value==='category'){await api('/categories',Object.fromEntries(Object.entries(form).filter(([key])=>key!=='originalCode')),'POST');categories.value=await api('/categories')}
 if(mode.value==='tier'){await api('/suppliers/'+selected.value.id+'/tier',{...form},'POST');await refreshSelected()}
 mode.value='';toast('已保存到服务器')
 }catch(e){error.value=e.message}finally{busy.value=false}}
async function download(path,name){try{const blob=await api(path,undefined,'GET',true);const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name.endsWith('.bin')?name.slice(0,-4)+({ 'application/pdf':'.pdf','image/png':'.png','image/jpeg':'.jpg' }[blob.type]||'.bin'):name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}}
async function scan(){busy.value=true;try{await api('/maintenance/certificate-warnings',{},'POST');await loadAlerts();toast('预警扫描完成')}catch(e){toast(e.message)}finally{busy.value=false}}
async function logout(){try{await request('/auth/'+realm.value+'/doLogout')}catch{}context.value=null;token.value='';clearData();sessionStorage.removeItem('srm-real-'+realm.value);await captchaConfig()}
function changeRealm(){token.value='';error.value='';captchaConfig()}
function applySearch(){page.value=1;load()}
onMounted(async()=>{try{if(token.value)await initialize();else await captchaConfig()}catch(e){error.value=e.message;context.value=null;await captchaConfig()}})
const certificateGroups=computed(()=>Object.entries((selected.value?.certificates||[]).reduce((m,c)=>{(m[c.certType]??=[]).push(c);return m},{})))
const modalTitle=computed(()=>({create:'新建供应商档案',edit:'编辑供应商档案',certificate:form.previousId?'续期资质 · 保留旧版本':'录入资质证书',contact:'新增联系人',contactEdit:'编辑联系人资料',access:'管理联系人权限',account:'开通供应商门户账号',category:'维护物料品类',tier:'调整供应商等级'}[mode.value]))
</script>
<template>
 <div v-if="!context" class="real-login"><div class="login-intro"><span class="login-logo">知源 SRM</span><h1>让优质合作，<br>从可信档案开始。</h1><p>供应商档案 · 资质管理 · 联系人协同</p><span class="login-foot">真实业务工作台 / W3–6</span></div><section class="login-card"><div class="eyebrow">SUPPLIER WORKSPACE</div><h2>登录工作台</h2><p class="muted">使用已开通的真实账号登录</p><div class="login-tabs"><button :class="{selected:realm==='b'}" @click="realm='b';changeRealm()">内部工作台</button><button :class="{selected:realm==='c'}" @click="realm='c';changeRealm()">供应商门户</button></div><form @submit.prevent="login"><label>账号<input aria-label="登录账号" v-model="loginForm.account" autocomplete="username" required /></label><label>密码<input aria-label="登录密码" v-model="loginForm.password" type="password" autocomplete="current-password" required /></label><label v-if="captchaOpen">图片验证码<div class="captcha-row"><input aria-label="图片验证码" v-model="loginForm.validCode" required /><button type="button" @click="refreshCaptcha"><img :src="captcha" alt="点击刷新验证码" /></button></div></label><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="btn primary login-submit" :disabled="busy">{{busy?'正在验证…':'登录工作台 →'}}</button></form><button v-if="realm==='c'" class="text-btn" @click="registrationOpen=true">首次合作？注册供应商</button><p class="login-note">身份、组织范围与角色均由服务器确定。<br>门户账号由内部管理员关联联系人后开通。</p></section></div>
 <div v-else :class="['app-shell','real-workspace',{embedded:props.embedded} ]">
  <aside v-if="!props.embedded" class="sidebar"><div class="brand"><span class="brand-mark">知</span><span>知源 <b>SRM</b><small>供应商协同管理平台</small></span></div><div class="workspace-label">业务工作空间</div><button :class="['nav-item',{active:view==='suppliers'}]" @click="view='suppliers'">▦　供应商档案</button><button :class="['nav-item',{active:view==='alerts'}]" @click="view='alerts';loadAlerts()">◷　资质预警 <span class="nav-count">{{alerts.length}}</span></button><button v-if="context.canClassify" :class="['nav-item',{active:view==='categories'}]" @click="view='categories'">▥　品类字典</button><button v-if="!context.portal" :class="['nav-item',{active:view==='approvals'}]" @click="view='approvals'">✓　审批工作台</button><div class="sidebar-bottom"><span class="status-dot"></span>真实业务环境<p>服务端身份 · MySQL 持久化</p><button @click="logout">退出登录</button></div></aside>
  <div class="main-shell"><header class="topbar"><div class="breadcrumb">供应链管理 <span>/</span><strong>{{context.portal?'供应商门户':'内部工作台'}}</strong></div><div class="topbar-actions"><span class="scope-chip">{{context.orgName||context.orgId}}</span><span class="scope-chip">{{context.roles.join(' / ')}}</span><button class="btn" @click="logout">退出登录</button></div></header>
   <main><div class="page-heading"><div><div class="eyebrow">SUPPLIER RELATIONSHIP MANAGEMENT</div><h1>{{view==='approvals'?'审批工作台':view==='alerts'?'资质预警':view==='categories'?'物料品类':'供应商档案'}}</h1><p>资料真实保存，权限由服务器校验，每次变更留下可验证记录。</p></div><div class="heading-actions"><button v-if="props.embedded&&!context.portal" class="btn" @click="view=view==='approvals'?'suppliers':'approvals'">{{view==='approvals'?'返回供应商档案':'审批工作台'}}</button><button v-if="view==='suppliers'" class="btn" @click="download('/suppliers-export?'+new URLSearchParams({searchKey:search,category,status,tier,orgId:orgFilter,sortBy,sortOrder}),'suppliers.xlsx')">导出 Excel</button><button v-if="!context.portal&&context.canManage&&view==='suppliers'" class="btn primary" @click="open('create')">＋ 新建供应商</button><button v-if="view==='categories'&&context.canClassify" class="btn primary" @click="open('category')">＋ 新建品类</button></div></div>
    <div class="real-scope"><span class="pulse"></span>{{context.portal?'仅可访问当前绑定供应商':'组织与数据范围来自当前登录会话'}}<span>全部操作通过真实业务接口 · 无模拟数据回退</span></div>
    <div v-if="error&&!mode" class="form-error" role="alert">{{error}}</div>
    <section v-if="view==='suppliers'" class="panel"><div class="panel-heading"><div><h2>供应商名录 <span class="scope-chip">{{total}} 家</span></h2><p>建立可信赖的供应网络</p></div><button class="btn" :disabled="busy" @click="load">{{busy?'加载中…':'刷新列表'}}</button></div><form class="table-toolbar" @submit.prevent="applySearch"><label class="search-field"><input aria-label="搜索供应商" v-model="search" placeholder="供应商名称或编码" /></label><select aria-label="品类筛选" v-model="category" @change="applySearch"><option value="">全部品类</option><option v-for="c in categories" :key="c.code" :value="c.code">{{c.name}}</option></select><select aria-label="状态筛选" v-model="status" @change="applySearch"><option value="">全部状态</option><option v-for="(name,key) in statusLabels" :key="key" :value="key">{{name}}</option></select><select aria-label="等级筛选" v-model="tier" @change="applySearch"><option value="">全部等级</option><option v-for="(name,key) in tierLabels" :key="key" :value="key">{{name}}</option></select><select aria-label="排序字段" v-model="sortBy" @change="applySearch"><option value="createTime">创建时间</option><option value="name">供应商名称</option><option value="supplierCode">供应商编码</option></select><select aria-label="排序方向" v-model="sortOrder" @change="applySearch"><option value="DESC">降序</option><option value="ASC">升序</option></select><label v-if="!context.portal&&context.scope!=='SELF'" class="search-field org-filter"><input aria-label="组织筛选" v-model="orgFilter" placeholder="组织ID（在授权范围内）" maxlength="20" /></label><button class="btn">查询</button></form><div class="table-scroll"><table><thead><tr><th>供应商名称</th><th>品类</th><th>等级</th><th>准入状态</th><th>信用代码</th><th>操作</th></tr></thead><tbody><tr v-for="s in rows" :key="s.id"><td><button class="supplier-cell" @click="show(s)"><span class="supplier-avatar" style="background:#eaf3ee">{{s.name.slice(0,1)}}</span><span><strong>{{s.name}}</strong><small>{{s.supplierCode}}</small></span></button></td><td>{{categories.find(c=>c.code===s.category)?.name||s.category}}</td><td>{{tierLabels[s.tier]||s.tier}}</td><td><SrmStatus :tone="s.status.toLowerCase()">{{statusLabels[s.status]}}</SrmStatus></td><td class="masked">{{s.creditCode}}</td><td><button class="text-btn" @click="show(s)">查看档案 ›</button></td></tr></tbody></table><div v-if="!rows.length&&!busy" class="empty-state"><h3>当前范围内暂无供应商</h3><p>{{context.portal?'请联系内部管理员核对档案绑定。':'新建一份档案，开始管理真实的合作伙伴。'}}</p></div></div><div class="table-footer"><span>共 {{total}} 条</span><div><button :disabled="page<=1" @click="page--;load()">‹</button><button class="current-page">{{page}}</button><button :disabled="page*20>=total" @click="page++;load()">›</button></div></div></section>
    <section v-if="view==='alerts'" class="panel"><div class="panel-heading"><div><h2>资质到期与过期提醒</h2><p>每日按配置扫描；同一证书有效期与预警类型去重。</p></div><button v-if="context.roles.includes('superAdmin')" class="btn" @click="scan">立即扫描</button></div><table><thead><tr><th>供应商</th><th>证书</th><th>到期日</th><th>类型</th><th>投递状态</th></tr></thead><tbody><tr v-for="a in alerts" :key="a.id"><td><button class="text-btn" @click="show({id:a.supplierId})">{{a.supplierId}}</button></td><td>{{a.certId}}</td><td>{{a.validTo}}</td><td>{{a.kind==='EXPIRED'?'已过期':'即将到期'}}</td><td>{{a.status==='SENT'?'已发送站内信':'等待接收人'}}</td></tr></tbody></table><div v-if="!alerts.length" class="empty-state">当前范围暂无预警</div></section>
    <section v-if="view==='approvals'" class="panel"><LifecyclePanel :api="api" :context="context" :categories="categories" @changed="load" @inspect="show({id:$event})" /></section>
    <section v-if="view==='categories'" class="panel"><div class="panel-heading"><h2>物料品类与准入资质要求</h2></div><table><thead><tr><th>编码</th><th>名称</th><th>必需资质</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="c in categories" :key="c.code"><td>{{c.code}}</td><td>{{c.name}}</td><td>{{JSON.parse(c.requiredCerts).map(t=>certLabels[t]).join(' / ')||'无'}}</td><td>{{c.enabled?'启用':'停用'}}</td><td><button class="text-btn" @click="open('category',c)">维护</button></td></tr></tbody></table></section>
    <footer class="page-footer"><span>知源 SRM · 真实业务工作台</span><span>档案 · 资质 · 联系人 · 真实审批</span></footer>
   </main></div>
  <SrmDrawer v-if="selected" :label="selected.name" @close="closeSupplier"><div class="drawer-top"><span class="eyebrow">SUPPLIER PROFILE</span><button class="icon-button" aria-label="关闭档案" @click="closeSupplier">✕</button></div><div class="drawer-heading"><span class="supplier-avatar large" style="background:#eaf3ee">{{selected.name.slice(0,1)}}</span><div><h2>{{selected.name}}</h2><p>{{selected.supplierCode}}</p></div></div><div class="drawer-badges"><SrmStatus :tone="selected.status.toLowerCase()">{{statusLabels[selected.status]}}</SrmStatus><span class="scope-chip">{{tierLabels[selected.tier]}}</span><span class="scope-chip">版本 {{selected.rowVersion}}</span></div><div class="detail-tabs"><button v-for="(label,key) in {profile:'基础资料',certificates:'资质证书',contacts:'联系人',lifecycle:'准入与审批',history:'变更记录'}" :key="key" :class="{selected:tab===key}" @click="tab=key">{{label}}</button></div><div class="drawer-content">
    <template v-if="tab==='profile'"><div class="inline-actions"><button v-if="context.canManage" class="btn" @click="open('edit')">编辑档案</button><button v-if="context.canClassify" class="btn" @click="open('tier')">调整等级</button></div><dl class="profile-grid"><div><dt>供应商名称</dt><dd>{{selected.name}}</dd></div><div><dt>物料品类</dt><dd>{{categories.find(c=>c.code===selected.category)?.name}}</dd></div><div><dt>信用代码</dt><dd>{{selected.creditCode}}</dd></div><div><dt>银行账号</dt><dd>{{selected.bankAccount||'未填写'}}</dd></div><div><dt>开户行</dt><dd>{{selected.bankName||'未填写'}}</dd></div><div><dt>归属组织</dt><dd>{{selected.orgId}}</dd></div><div class="full"><dt>注册地址</dt><dd>{{selected.address||'未填写'}}</dd></div></dl><div class="info-note">{{context.sensitive?'当前账号获授权查看敏感字段。':'敏感字段按权限脱敏展示。'}} 已准入档案的银行账号及信用代码变更需审批；当前阶段不开放直接状态修改。</div></template>
    <template v-if="tab==='certificates'"><div class="inline-actions"><span :class="['status',selected.qualification.complete?'qualified':'reviewing']">{{selected.qualification.complete?'准入资质齐备':'缺失：'+selected.qualification.missing.map(x=>certLabels[x]).join('、')}}</span><button v-if="context.canManage" class="btn primary" @click="open('certificate')">＋ 录入资质</button></div><section v-for="[type,certificates] in certificateGroups" :key="type"><h3 class="section-title">{{certLabels[type]}} <span>{{certificates.length}} 个版本</span></h3><article class="certificate" v-for="c in certificates" :key="c.id"><span class="certificate-icon">▤</span><div><strong>{{certLabels[c.certType]}} · v{{c.version}}</strong><small>{{c.certNo}}</small><p>{{c.validFrom}} — {{c.validTo}}</p><button class="text-btn" @click="preview(c.fileId)">预览附件</button><button class="text-btn" @click="download('/attachments/'+c.fileId,'certificate-'+c.fileId+'.bin')">下载附件</button></div><div class="cert-right"><span :class="['status',c.status==='VALID'?'qualified':c.status==='EXPIRED'?'frozen':c.status==='VOID'?'archived':'potential']">{{{VALID:'有效',EXPIRED:'过期',PENDING:'未生效',VOID:'已被续期'}[c.status]}}</span><button v-if="context.canManage&&c.status!=='VOID'" class="text-btn" @click="open('certificate',c)">续期</button></div></article></section><div v-if="!selected.certificates.length" class="empty-state">尚未录入资质。请上传真实附件并填写有效期。</div></template>
    <template v-if="tab==='contacts'"><div class="inline-actions"><span class="muted small-copy">至少保留一位启用的管理员</span><button v-if="context.canManage" class="btn primary" @click="open('contact')">＋ 新增联系人</button></div><article class="real-contact" v-for="c in selected.contacts" :key="c.id"><div class="contact-card"><span class="avatar">{{c.name.slice(0,1)}}</span><div><strong>{{c.name}}</strong><p>{{c.phone}} · {{c.enabled?'启用':'停用'}}</p><small>{{c.email}}</small></div></div><div class="contact-role-tags"><span class="scope-chip" v-for="r in c.roles" :key="r">{{roleLabels[r]}}</span><span class="scope-chip">{{c.accountBound?'门户已开通':'门户未开通'}}</span></div><div v-if="context.canManage" class="inline-actions"><button class="text-btn" @click="open('contactEdit',c)">编辑资料</button><button class="text-btn" @click="open('access',c)">角色 / 启停</button><button v-if="!context.portal&&!c.accountBound&&c.enabled" class="text-btn" @click="open('account',c)">开通门户账号</button></div></article><div v-if="!selected.contacts.length" class="empty-state">新增第一位联系人时，请授予管理员角色。</div></template>
    <LifecyclePanel v-if="tab==='lifecycle'" :api="api" :context="context" :supplier="selected" :categories="categories" @changed="refreshSelected" @inspect="tab='certificates'" />
    <template v-if="tab==='history'"><article class="history-item" v-for="e in selected.events" :key="e.id"><strong>{{operationLabels[e.action]||e.action}}<span :class="['status',e.signatureValid?'qualified':'frozen']">{{e.signatureValid?'签名有效':'签名异常'}}</span></strong><p>{{e.time}}</p><small>操作人 {{e.actorId}}</small></article><p v-if="!selected.events.length" class="muted">暂无变更记录</p></template>
   </div><div class="drawer-footer"><span>真实数据库记录 · 服务端权限校验</span><button class="btn" @click="closeSupplier">关闭档案</button></div></SrmDrawer>
 </div>
 <SrmModal v-if="mode" :title="modalTitle" @close="mode=''"><form @submit.prevent="save">
  <template v-if="['create','edit'].includes(mode)"><label v-if="mode==='create'">供应商编码（留空自动生成）<input aria-label="供应商编码" v-model="form.supplierCode" maxlength="32" pattern="[A-Z0-9][A-Z0-9_-]{2,31}" placeholder="可填写自定义唯一编码" /></label><label>供应商名称 *<input aria-label="供应商名称" v-model="form.name" required maxlength="128" /></label><label>物料品类 *<select aria-label="物料品类" v-model="form.category" required><option v-for="c in categories.filter(c=>c.enabled||c.code===form.category)" :value="c.code" :key="c.code">{{c.name}}</option></select></label><label>信用代码{{mode==='create'?' *':'（留空保持原值）'}}<input aria-label="信用代码" v-model="form.creditCode" :required="mode==='create'" minlength="18" maxlength="18" autocomplete="off" /></label><label>银行账号{{mode==='edit'?'（留空保持原值）':''}}<input aria-label="银行账号" v-model="form.bankAccount" maxlength="64" autocomplete="off" /></label><label>开户行<input aria-label="开户行" v-model="form.bankName" maxlength="64" /></label><label>注册地址<input aria-label="注册地址" v-model="form.address" maxlength="255" /></label></template>
  <template v-if="mode==='certificate'"><label>资质类型 *<select aria-label="资质类型" v-model="form.certType" :disabled="!!form.previousId"><option v-for="(name,key) in certLabels" :key="key" :value="key">{{name}}</option></select></label><label>证书编号 *<input aria-label="证书编号" v-model="form.certNo" required maxlength="64" /></label><div class="date-fields"><label>生效日期 *<input aria-label="生效日期" type="date" v-model="form.validFrom" required /></label><label>到期日期 *<input aria-label="到期日期" type="date" v-model="form.validTo" :min="form.validFrom" required /></label></div><label>资质附件 *<input aria-label="资质附件" type="file" accept=".pdf,.png,.jpg,.jpeg" @change="file=$event.target.files[0]" required /></label><p class="small-copy muted">PDF、PNG或JPEG，最大10MB。文件保存在私有存储，下载需要供应商访问权限。续期保留旧版本。</p></template>
  <template v-if="['contact','contactEdit'].includes(mode)"><label>姓名 *<input aria-label="联系人姓名" v-model="form.name" required maxlength="32" /></label><label>手机号 *<input aria-label="联系人手机号" v-model="form.phone" required pattern="1[3-9][0-9]{9}" placeholder="请输入完整手机号，服务端加密保存" /></label><label>邮箱<input aria-label="联系人邮箱" v-model="form.email" type="email" maxlength="64" /></label></template>
  <template v-if="['contact','contactEdit','access'].includes(mode)"><fieldset class="role-options"><legend>门户角色</legend><label v-for="(name,key) in roleLabels" :key="key"><input type="checkbox" v-model="form.roles" :value="key" />{{name}}</label></fieldset><label class="check-label"><input type="checkbox" v-model="form.enabled" /> 启用该联系人</label><div class="info-note">角色取并集；停用会禁用对应门户账号。最后一位启用的管理员不可移除或停用。</div></template>
  <template v-if="mode==='account'"><label>门户登录账号 *<input aria-label="门户登录账号" v-model="form.account" required pattern="[A-Za-z0-9_.-]{4,64}" autocomplete="off" /></label><label>初始密码 *<input aria-label="初始密码" type="password" v-model="form.password" required minlength="12" autocomplete="new-password" /></label><div class="info-note">至少12位，包含字母与数字，并满足系统密码策略。密码经SM2加密传输；开通后请通过受控渠道交付联系人。</div></template>
  <template v-if="mode==='category'"><label>品类编码 *<input aria-label="品类编码" v-model="form.code" :disabled="!!form.originalCode" required pattern="[A-Z][A-Z0-9_]{1,31}" /></label><label>品类名称 *<input aria-label="品类名称" v-model="form.name" required maxlength="64" /></label><fieldset class="role-options"><legend>准入所需资质</legend><label v-for="(name,key) in certLabels" :key="key"><input type="checkbox" v-model="form.requiredCerts" :value="key" />{{name}}</label></fieldset><label class="check-label"><input type="checkbox" v-model="form.enabled" /> 启用品类</label></template>
  <template v-if="mode==='tier'"><label>供应商等级<select aria-label="供应商等级" v-model="form.tier"><option v-for="(name,key) in tierLabels" :key="key" :value="key">{{name}}</option></select></label></template>
  <p v-if="error" class="form-error" role="alert">{{error}}</p><div class="modal-actions"><button type="button" class="btn" @click="mode=''">取消</button><button class="btn primary" :disabled="busy" type="submit">{{busy?'正在保存…':'保存到服务器'}}</button></div>
 </form></SrmModal>
<SrmModal v-if="previewUrl" title="资质附件预览" @close="closePreview"><img v-if="previewType.startsWith('image/')" :src="previewUrl" alt="资质附件" style="max-width:100%" /><iframe v-else :src="previewUrl" title="资质附件预览" sandbox="" style="width:100%;height:60vh;border:0" /><p class="muted">如浏览器不支持预览，可关闭后下载附件查看。</p></SrmModal>
 <RegistrationForm v-if="registrationOpen&&!context" @close="registrationOpen=false" />
 <div v-if="notice" class="toast" role="status">{{notice}}</div>
</template>
